mesSim(document.getElementById("sim-l38"),Object.assign({id:"l38"},{kind:"web",title:"Trang trạng thái tối thiểu",sub:"Sửa HTML, CSS, JS rồi bấm Xem trước. fetch tới /machines/state trả dữ liệu giả lập của ba máy.",api:{"/machines/state":[{machine_id:"L1-M1",state:"RUNNING",since:"2026-11-12T08:12:00+07:00"},{machine_id:"L1-M2",state:"DOWN",since:"2026-11-12T09:40:00+07:00"},{machine_id:"L1-M3",state:"IDLE",since:"2026-11-12T09:49:00+07:00"}],
 "/machines":[{machine_id:"L1-M1",state:"RUNNING"},{machine_id:"L1-M2",state:"DOWN"},{machine_id:"L1-M3",state:"IDLE"}],"/lines/L1/status":[{machine_id:"L1-M1",state:"RUNNING",since:"2026-11-12T08:12:00+07:00"},{machine_id:"L1-M2",state:"DOWN",since:"2026-11-12T09:40:00+07:00"},{machine_id:"L1-M3",state:"IDLE",since:"2026-11-12T09:49:00+07:00"}]},
 html:"<h1>Dây chuyền L1</h1>\n<div id=\"machines\" class=\"grid\"></div>",
 css:".grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; }\n.card { border: 2px solid #999; border-radius: 8px; padding: 16px; font-size: 1.2rem; }\n.RUNNING { background: #d9f2e6; }\n/* thêm màu cho DOWN và IDLE */",
 js:"async function load() {\n  const r = await fetch(\"/machines/state\");\n  const data = await r.json();\n  document.getElementById(\"machines\").innerHTML = data.map(m =>\n    `<div class=\"card ${m.state}\">${m.machine_id}<br><b>${m.state}</b></div>`).join(\"\");\n}\nload();",
 tasks:[{t:"Bấm Xem trước: ba thẻ máy hiện ra.",check:(s,c)=>c.has("render",e=>/L1-M1/.test(e.text)&&/L1-M3/.test(e.text))},
  {t:"Thêm màu cho lớp <code>.DOWN</code> và <code>.IDLE</code> trong CSS rồi xem lại.",hint:".DOWN { background: #f8d7d5; } .IDLE { background: #fde8c8; }",ok:"Lớp CSS theo tên trạng thái: thêm trạng thái chỉ cần thêm một dòng CSS.",check:s=>/\.DOWN\s*\{[^}]*background/.test(s.code().css)&&/\.IDLE\s*\{[^}]*background/.test(s.code().css)},
  {t:"Không dựa riêng vào màu: thêm biểu tượng hoặc chữ tiếng Việt cho trạng thái trong JS (ví dụ LỖI cho DOWN).",check:(s,c)=>c.has("render",e=>/LỖI|⚠|✖|DỪNG/.test(e.text))}]}));

